// Read the seat count from a parsed request body.
// unknown: we do not trust the body until every part is checked.
export function readSeats(data: unknown): number {
  if (typeof data === 'object' && data !== null && 'seats' in data) {
    const seats = data.seats;            // still unknown here
    if (typeof seats === 'number' && Number.isInteger(seats) && seats >= 1) {
      return seats;                      // narrowed to number
    }
  }
  throw new RangeError('seats must be a positive integer');
}

