// Late fee: the first 15 minutes are free, then 10,000 VND per started 30 minutes.
export function lateFee(minutesLate) {
  if (minutesLate <= 15) return 0;
  return Math.ceil((minutesLate - 15) / 30) * 10000;
}

export function totalFees(bookings) {
  let total = 0;
  for (const b of bookings) total += lateFee(b.minutesLate);
  return total;
}

export function formatVnd(amount) {
  return amount.toLocaleString('en-US') + ' VND';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { lateFee, totalFees, formatVnd } from '../src/fees.ts';

test('15 minutes late is free', () => assert.equal(lateFee(15), 0));
test('16 minutes late costs one block', () => assert.equal(lateFee(16), 10000));
test('46 minutes late costs two blocks', () => assert.equal(lateFee(46), 20000));
test('totals a list', () => assert.equal(totalFees([{ minutesLate: 20 }, { minutesLate: 50 }]), 30000));
test('formats VND', () => assert.equal(formatVnd(30000), '30,000 VND'));

